<?php
if(!defined('SCHOOLOS_SERVICES_LIBRARY')){header('Location: index.php?s=services&area=library');exit;}
function lib_schema():array{return [
 "CREATE TABLE IF NOT EXISTS lib_meta(tenant_id BIGINT UNSIGNED NOT NULL,book_id BIGINT UNSIGNED NOT NULL,shelf VARCHAR(120) NOT NULL DEFAULT '',daily_fine_kobo BIGINT NOT NULL DEFAULT 0,replacement_kobo BIGINT NOT NULL DEFAULT 0,PRIMARY KEY(tenant_id,book_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS lib_reservations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,book_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'waiting',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id,book_id,status,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS lib_charges(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,loan_id BIGINT UNSIGNED NOT NULL,kind VARCHAR(20) NOT NULL,amount_kobo BIGINT NOT NULL,invoice_id BIGINT UNSIGNED NOT NULL,created_by BIGINT UNSIGNED NOT NULL,UNIQUE KEY once_charge(tenant_id,loan_id,kind)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS lib_alerts(tenant_id BIGINT UNSIGNED NOT NULL,loan_id BIGINT UNSIGNED NOT NULL,alert_day DATE NOT NULL,PRIMARY KEY(tenant_id,loan_id,alert_day)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS lib_resources(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,title VARCHAR(220) NOT NULL,kind VARCHAR(20) NOT NULL,url VARCHAR(1500) NOT NULL,licensor VARCHAR(180) NOT NULL,starts_on DATE NOT NULL,ends_on DATE NOT NULL,seats INT NOT NULL DEFAULT 0,active TINYINT NOT NULL DEFAULT 1,INDEX(tenant_id,active)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS lib_access(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,resource_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,expires_at DATETIME NOT NULL,returned_at DATETIME NULL,INDEX(tenant_id,resource_id,expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"
];}
function lib_isbn(string $raw):string{$v=strtoupper(str_replace(['-',' '],'',$raw));if($v==='')return '';if(preg_match('/^\d{9}[\dX]$/D',$v)){$sum=0;for($i=0;$i<10;$i++)$sum+=(10-$i)*($v[$i]==='X'?10:(int)$v[$i]);if($sum%11===0)return $v;}if(preg_match('/^\d{13}$/D',$v)){$sum=0;for($i=0;$i<13;$i++)$sum+=(int)$v[$i]*($i%2?3:1);if($sum%10===0)return $v;}throw new RuntimeException('ISBN checksum is invalid; leave blank for books without an ISBN.');}
function lib_issue_gate(array $u,int $book,int $student):void{if(!op_has('lib_reservations'))return;$first=q("SELECT * FROM lib_reservations WHERE tenant_id=? AND book_id=? AND status='waiting' ORDER BY id LIMIT 1 FOR UPDATE",[$u['tenant_id'],$book])->fetch();if($first&&(int)$first['student_id']!==$student)throw new RuntimeException('The first waiting reservation has priority. Cancel it explicitly if no longer needed.');if($first)q("UPDATE lib_reservations SET status='fulfilled' WHERE tenant_id=? AND id=?",[$u['tenant_id'],$first['id']]);}
function lib_resource_access(array $u,int $id):array{$r=sv_own('lib_resources',$u,$id);$today=date('Y-m-d');if(!$r['active']||$r['starts_on']>$today||$r['ends_on']<$today)throw new RuntimeException('Resource licence is inactive or outside its dates.');if($r['kind']==='ebook'&&!g('SELECT id FROM lib_access WHERE tenant_id=? AND resource_id=? AND user_id=? AND returned_at IS NULL AND expires_at>NOW()',[$u['tenant_id'],$id,$u['id']]))throw new RuntimeException('Borrow an available licensed ebook seat first.');return $r;}
function lib_charge(array $u,array $loan,string $kind,int $amount):void{global $pdo;if(g('SELECT id FROM lib_charges WHERE tenant_id=? AND loan_id=? AND kind=?',[$u['tenant_id'],$loan['id'],$kind]))return;if($amount<=0)return;$invoice=sv_invoice($u,(int)$loan['student_id'],'LIB-'.$kind.'-'.$loan['id'],$amount,'Library '.$kind.' — loan #'.$loan['id']);q('INSERT INTO lib_charges(tenant_id,loan_id,kind,amount_kobo,invoice_id,created_by) VALUES(?,?,?,?,?,?)',[$u['tenant_id'],$loan['id'],$kind,$amount,$invoice,$u['id']]);}
function lib_action(array $u,string $a):string{
 global $pdo;$tid=(int)$u['tenant_id'];$manager=sv_can($u,'librarian');
 if(in_array($a,['reserve','cancel_reservation','request'],true)){$sid=op_id('student_id');sv_student($u,$sid,'librarian');return sv_tx(function()use($u,$a,$sid,$tid){$b=sv_own('books',$u,op_id('book_id'),true);if($a==='cancel_reservation'){q("UPDATE lib_reservations SET status='cancelled' WHERE tenant_id=? AND book_id=? AND student_id=? AND status='waiting'",[$tid,$b['id'],$sid]);return 'Reservation cancelled.';}if($a==='reserve'){if(g("SELECT id FROM lib_reservations WHERE tenant_id=? AND book_id=? AND student_id=? AND status='waiting'",[$tid,$b['id'],$sid]))throw new RuntimeException('A waiting reservation already exists.');q('INSERT INTO lib_reservations(tenant_id,book_id,student_id) VALUES(?,?,?)',[$tid,$b['id'],$sid]);return 'Reservation queued in order.';}if((int)$b['available']<1||g("SELECT id FROM lp_library_loans WHERE tenant_id=? AND book_id=? AND student_id=? AND status IN ('requested','issued')",[$tid,$b['id'],$sid]))throw new RuntimeException('Book unavailable or a loan/request already exists.');q('INSERT INTO lp_library_loans(tenant_id,book_id,student_id) VALUES(?,?,?)',[$tid,$b['id'],$sid]);return 'Loan requested in the existing library register.';});}
 if($a==='ebook_borrow'||$a==='ebook_return'){return sv_tx(function()use($u,$a,$tid){$r=sv_own('lib_resources',$u,op_id('resource_id'),true);if($a==='ebook_return'){q('UPDATE lib_access SET returned_at=NOW() WHERE tenant_id=? AND resource_id=? AND user_id=? AND returned_at IS NULL',[$tid,$r['id'],$u['id']]);return 'Ebook seat returned.';}if($r['kind']!=='ebook'||!$r['active']||$r['starts_on']>date('Y-m-d')||$r['ends_on']<date('Y-m-d'))throw new RuntimeException('Licensed ebook unavailable.');if(g('SELECT id FROM lib_access WHERE tenant_id=? AND resource_id=? AND user_id=? AND returned_at IS NULL AND expires_at>NOW()',[$tid,$r['id'],$u['id']]))return 'Your ebook seat is already active.';if((int)g('SELECT COUNT(*) FROM lib_access WHERE tenant_id=? AND resource_id=? AND returned_at IS NULL AND expires_at>NOW()',[$tid,$r['id']])>=(int)$r['seats'])throw new RuntimeException('All licensed seats are in use.');$end=min(date('Y-m-d H:i:s',time()+7*86400),$r['ends_on'].' 23:59:59');q('INSERT INTO lib_access(tenant_id,resource_id,user_id,expires_at) VALUES(?,?,?,?)',[$tid,$r['id'],$u['id'],$end]);return 'Ebook seat borrowed for up to seven days within the licence period.';});}
 sv_need($u,'librarian');
 if($a==='catalogue'){return sv_tx(function()use($u,$tid){$id=op_id('book_id');$title=op_text('title',220,true);$author=op_text('author',180,true);$isbn=lib_isbn(op_text('isbn',80));if($id){sv_own('books',$u,$id,true);q('UPDATE books SET title=?,author=?,isbn=? WHERE tenant_id=? AND id=?',[$title,$author,$isbn,$tid,$id]);}else{q('INSERT INTO books(tenant_id,title,author,isbn,copies,available) VALUES(?,?,?,?,0,0)',[$tid,$title,$author,$isbn]);$id=(int)($GLOBALS['pdo']->lastInsertId());}q('INSERT INTO lib_meta(tenant_id,book_id,shelf,daily_fine_kobo,replacement_kobo) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE shelf=VALUES(shelf),daily_fine_kobo=VALUES(daily_fine_kobo),replacement_kobo=VALUES(replacement_kobo)',[$tid,$id,op_text('shelf',120),op_money(op_text('daily_fine',20,true),true),op_money(op_text('replacement',20,true),true)]);audit('library.catalogue','book',(string)$id);return 'Book catalogue saved; existing loans retained.';});}
 if($a==='copies'){return sv_tx(function()use($u,$tid){$b=sv_own('books',$u,op_id('book_id'),true);$raw=op_text('delta',8,true);if(!preg_match('/^-?\d{1,6}$/D',$raw)||(int)$raw===0)throw new RuntimeException('Enter a nonzero whole-copy adjustment.');$d=(int)$raw;if((int)$b['copies']+$d<0||(int)$b['available']+$d<0)throw new RuntimeException('Cannot remove copies on loan or exceed available stock.');q('UPDATE books SET copies=copies+?,available=available+? WHERE tenant_id=? AND id=?',[$d,$d,$tid,$b['id']]);audit('library.copies','book',$b['id'].' '.$d.' '.op_text('reason',300,true));return 'Copies adjusted with an audit record.';});}
 if(in_array($a,['issue','return','reject','lost','recover','fine'],true)){$loan=sv_own('lp_library_loans',$u,op_id('loan_id'));return sv_tx(function()use($u,$tid,$loan,$a){$b=sv_own('books',$u,(int)$loan['book_id'],true);$l=sv_own('lp_library_loans',$u,(int)$loan['id'],true);$meta=q('SELECT * FROM lib_meta WHERE tenant_id=? AND book_id=?',[$tid,$b['id']])->fetch()?:['daily_fine_kobo'=>0,'replacement_kobo'=>0];$status=$l['status'];
  if($a==='issue'){if($status!=='requested'||(int)$b['available']<1)throw new RuntimeException('Requested loan and available copy required.');$due=op_date(op_text('due_on',10,true));if($due<date('Y-m-d'))throw new RuntimeException('Due date cannot be in the past.');lib_issue_gate($u,(int)$b['id'],(int)$l['student_id']);q('UPDATE books SET available=available-1 WHERE tenant_id=? AND id=?',[$tid,$b['id']]);q("UPDATE lp_library_loans SET status='issued',due_on=?,reviewed_by=? WHERE tenant_id=? AND id=?",[$due,$u['id'],$tid,$l['id']]);}
  elseif($a==='reject'){if($status!=='requested')throw new RuntimeException('Only pending requests can be rejected.');q("UPDATE lp_library_loans SET status='rejected',reviewed_by=? WHERE tenant_id=? AND id=?",[$u['id'],$tid,$l['id']]);}
  elseif($a==='recover'){if($status!=='lost')throw new RuntimeException('Only a recorded lost copy can be recovered.');q('UPDATE books SET copies=copies+1,available=available+1 WHERE tenant_id=? AND id=?',[$tid,$b['id']]);q("UPDATE lp_library_loans SET status='returned',returned_at=NOW(),reviewed_by=? WHERE tenant_id=? AND id=?",[$u['id'],$tid,$l['id']]);}
  elseif($a==='fine'){if(!in_array($status,['issued','returned','lost'],true)||!$l['due_on'])throw new RuntimeException('Loan has no eligible due date.');$until=$status==='returned'?substr($l['returned_at'],0,10):date('Y-m-d');$days=max(0,(int)(new DateTimeImmutable($l['due_on']))->diff(new DateTimeImmutable($until))->format('%r%a'));lib_charge($u,$l,'fine',$days*(int)$meta['daily_fine_kobo']);}
  else{if($status!=='issued')throw new RuntimeException('Only issued loans can be returned or marked lost.');if($a==='return'){q('UPDATE books SET available=available+1 WHERE tenant_id=? AND id=?',[$tid,$b['id']]);q("UPDATE lp_library_loans SET status='returned',returned_at=NOW(),reviewed_by=? WHERE tenant_id=? AND id=?",[$u['id'],$tid,$l['id']]);}else{q('UPDATE books SET copies=copies-1 WHERE tenant_id=? AND id=? AND copies>0',[$tid,$b['id']]);q("UPDATE lp_library_loans SET status='lost',reviewed_by=? WHERE tenant_id=? AND id=?",[$u['id'],$tid,$l['id']]);lib_charge($u,$l,'loss',(int)$meta['replacement_kobo']);}}
  audit('library.'.$a,'loan',(string)$l['id']);return 'Library transaction recorded once. Charges use existing Finance; refunds require Finance review.';});}
 if($a==='resource'){$kind=sv_enum('kind',['digital','ebook']);$start=op_date(op_text('starts_on',10,true));$end=op_date(op_text('ends_on',10,true));if($end<$start)throw new RuntimeException('Licence dates invalid.');$seats=$kind==='ebook'?sv_qty('seats',10000):0;q('INSERT INTO lib_resources(tenant_id,title,kind,url,licensor,starts_on,ends_on,seats) VALUES(?,?,?,?,?,?,?,?)',[$tid,op_text('title',220,true),$kind,sv_https(op_text('url',1500,true)),op_text('licensor',180,true),$start,$end,$seats]);return 'Resource registered with licence dates and seat limits.';}
 if($a==='disable_resource'){$r=sv_own('lib_resources',$u,op_id('resource_id'));q('UPDATE lib_resources SET active=0 WHERE tenant_id=? AND id=?',[$tid,$r['id']]);return 'Resource access disabled.';}
 if($a==='overdue'){return sv_tx(function()use($u,$tid){$rows=q("SELECT l.*,b.title FROM lp_library_loans l JOIN books b ON b.id=l.book_id AND b.tenant_id=l.tenant_id WHERE l.tenant_id=? AND l.status='issued' AND l.due_on<CURRENT_DATE() ORDER BY l.id LIMIT 500",[$tid])->fetchAll();$count=0;foreach($rows as $l){if(q('INSERT IGNORE INTO lib_alerts VALUES(?,?,CURRENT_DATE())',[$tid,$l['id']])->rowCount()!==1)continue;foreach(q("SELECT DISTINCT u.id FROM ecosystem_links e JOIN users u ON u.id=e.user_id AND u.tenant_id=e.tenant_id WHERE e.tenant_id=? AND e.student_id=? AND e.relation_type IN ('parent','student') AND u.active=1",[$tid,$l['student_id']])->fetchAll() as $r)q("INSERT INTO cm_posts(tenant_id,author_id,title,body,audience,recipient_id) VALUES(?,?,?,?,'all',?)",[$tid,$u['id'],'Library overdue reminder','Please return '.$l['title'].' (due '.$l['due_on'].').',$r['id']]);$count++;}return $count.' overdue reminders posted in Community Hub (once per loan/day).';});}
 throw new RuntimeException('Unsupported library action.');
}
/** Fixed QR version 2-L, byte mode, mask 0. Labels contain only a catalogue key, never a credential. */
function lib_qr(string $text):string{
 if(strlen($text)>32)throw new RuntimeException('Catalogue key too long.');$bits='0100'.str_pad(decbin(strlen($text)),8,'0',STR_PAD_LEFT);foreach(str_split($text) as $ch)$bits.=str_pad(decbin(ord($ch)),8,'0',STR_PAD_LEFT);$bits.=str_repeat('0',min(4,272-strlen($bits)));$bits.=str_repeat('0',(8-strlen($bits)%8)%8);$data=array_map('bindec',str_split($bits,8));for($i=0;count($data)<34;$i++)$data[]=$i%2?17:236;
 $mul=static function(int $a,int $b):int{$r=0;for(;$b;$b>>=1){if($b&1)$r^=$a;$a<<=1;if($a&256)$a^=285;}return $r;};$gen=[1];$x=1;for($i=0;$i<10;$i++){$next=array_fill(0,count($gen)+1,0);foreach($gen as $j=>$v){$next[$j]^=$v;$next[$j+1]^=$mul($v,$x);}$gen=$next;$x=$mul($x,2);}$rem=array_fill(0,10,0);foreach($data as $v){$f=$v^$rem[0];array_shift($rem);$rem[]=0;for($i=0;$i<10;$i++)$rem[$i]^=$mul($gen[$i+1],$f);}$stream='';foreach(array_merge($data,$rem) as $v)$stream.=str_pad(decbin($v),8,'0',STR_PAD_LEFT);
 $n=25;$m=array_fill(0,$n,array_fill(0,$n,null));$set=static function($x,$y,$v)use(&$m,$n){if($x>=0&&$y>=0&&$x<$n&&$y<$n)$m[$y][$x]=(bool)$v;};foreach([[0,0],[18,0],[0,18]] as [$fx,$fy])for($y=-1;$y<=7;$y++)for($x=-1;$x<=7;$x++)$set($fx+$x,$fy+$y,$x>=0&&$x<=6&&$y>=0&&$y<=6&&($x===0||$x===6||$y===0||$y===6||($x>=2&&$x<=4&&$y>=2&&$y<=4)));for($i=8;$i<17;$i++){$set(6,$i,$i%2===0);$set($i,6,$i%2===0);}for($dy=-2;$dy<=2;$dy++)for($dx=-2;$dx<=2;$dx++)$set(18+$dx,18+$dy,max(abs($dx),abs($dy))!==1);
 $format=0x77c4;for($i=0;$i<15;$i++){$v=($format>>$i)&1;if($i<6)$set(8,$i,$v);elseif($i<8)$set(8,$i+1,$v);elseif($i===8)$set(7,8,$v);else $set(14-$i,8,$v);if($i<8)$set($n-1-$i,8,$v);else $set(8,$n-15+$i,$v);}$set(8,$n-8,1);
 $bit=0;$up=true;for($right=$n-1;$right>=1;$right-=2){if($right===6)$right=5;for($v=0;$v<$n;$v++){$y=$up?$n-1-$v:$v;for($j=0;$j<2;$j++){$x=$right-$j;if($m[$y][$x]!==null)continue;$value=($stream[$bit++]??'0')==='1';$m[$y][$x]=$value^(($x+$y)%2===0);}}$up=!$up;}$path='';foreach($m as $y=>$row)foreach($row as $x=>$v)if($v)$path.='M'.($x+4).' '.($y+4).'h1v1h-1z';return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 33 33" role="img" aria-label="Book catalogue QR"><rect width="33" height="33" fill="white"/><path d="'.$path.'" fill="black"/></svg>';
}
function lib_render(array $u):void{
 $tid=(int)$u['tenant_id'];$manager=sv_can($u,'librarian');$tabs=['catalogue'=>'Catalogue & ISBN','resources'=>'Digital resources & licensed ebooks','loans'=>'Lending & returns','reservations'=>'Reservations','overdue'=>'Overdue alerts & fines','history'=>'Reading history','reports'=>'Inventory reports','labels'=>'Barcode / QR labels'];if(!$manager)unset($tabs['reports'],$tabs['labels']);$view=sv_tabs('library',$tabs,'catalogue');op_card($tabs[$view]);$books=q('SELECT b.*,COALESCE(m.shelf,\'\') shelf FROM books b LEFT JOIN lib_meta m ON m.book_id=b.id AND m.tenant_id=b.tenant_id WHERE b.tenant_id=? ORDER BY b.title LIMIT 1000',[$tid])->fetchAll();$bc=op_choices($books,'title');$sc=$manager?op_choices(q('SELECT id,name FROM students WHERE tenant_id=? ORDER BY name',[$tid])->fetchAll()):sv_children($u);$ef=['student_id'=>['Student',$sc],'book_id'=>['Book',$bc]];
 if($view==='catalogue'){
  echo '<form method="get"><input type="hidden" name="s" value="services"><input type="hidden" name="area" value="library"><input type="hidden" name="view" value="catalogue"><label>Search title, author, ISBN or scan catalogue key <input name="search" value="'.e(is_string($_GET['search']??null)?$_GET['search']:'').'" id="libScan"></label><button class="btn">Search</button><button type="button" class="btn" id="libCamera">Scan QR / barcode</button><video id="libVideo" playsinline muted style="display:none;width:300px"></video><span id="libScanStatus"></span></form><script>(()=>{const b=document.getElementById("libCamera"),v=document.getElementById("libVideo"),s=document.getElementById("libScanStatus"),i=document.getElementById("libScan");b.onclick=async()=>{if(!window.BarcodeDetector||!navigator.mediaDevices){s.textContent="Use a USB scanner or enter the printed key / ISBN.";return}let stream;try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:"environment"}});v.srcObject=stream;v.style.display="block";await v.play();const d=new BarcodeDetector();const end=()=>{stream.getTracks().forEach(t=>t.stop());v.style.display="none"};const deadline=Date.now()+30000;const scan=async()=>{if(Date.now()>deadline){end();s.textContent="Scan timed out; try again.";return}try{const c=await d.detect(v);if(c.length){i.value=c[0].rawValue;end();s.textContent="Scanned; select Search to review.";return}}catch(e){}requestAnimationFrame(scan)};scan()}catch(e){if(stream)stream.getTracks().forEach(t=>t.stop());s.textContent="Camera unavailable or permission denied."}}})();</script>';
  $search=is_string($_GET['search']??null)?trim($_GET['search']):'';$rows=array_filter($books,fn($b)=>$search===''||stripos($b['title'].' '.$b['author'].' '.$b['isbn'],$search)!==false||$search==='LIB-'.$tid.'-'.$b['id']);op_table(array_map(fn($b)=>[$b['id'],$b['title'],$b['author'],$b['isbn'],$b['shelf'],$b['copies'],$b['available']],array_values($rows)),['ID','Title','Author','ISBN','Shelf','Copies','Available']);if($sc)sv_form('lib_request',$ef,'Request a loan');if($manager){sv_form('lib_catalogue',['book_id'=>['Book ID (0 for a new title)','number','0'],'title'=>['Title','text'],'author'=>['Author','text'],'isbn'=>['ISBN (optional, checksum validated)','text','',false],'shelf'=>['Shelf','text','',false],'daily_fine'=>['Daily overdue fine (NGN)','text','0'],'replacement'=>['Replacement cost (NGN)','text','0']],'Save catalogue');sv_form('lib_copies',['book_id'=>['Book',$bc],'delta'=>['Copies received (+) / removed (-)','number'],'reason'=>['Adjustment reason','text']],'Adjust available copies');}
 }elseif($view==='resources'){
  $rows=q('SELECT id,title,kind,licensor,starts_on,ends_on,seats,active FROM lib_resources WHERE tenant_id=? ORDER BY id DESC',[$tid])->fetchAll();op_table($rows,['ID','Resource','Type','Licensor','From','To','Seats','Active']);foreach($rows as $r){if(!$r['active'])continue;echo '<p><a href="?sv_resource='.(int)$r['id'].'">Open '.e($r['title']).'</a></p>';if($r['kind']==='ebook'){sv_form('lib_ebook_borrow',['resource_id'=>['Ebook',[$r['id']=>$r['title']]]],'Borrow licensed seat');sv_form('lib_ebook_return',['resource_id'=>['Ebook',[$r['id']=>$r['title']]]],'Return my seat');}}
  echo '<p>Links require a current school account and an active licence; ebooks also require a seat. Publisher authentication and redistribution rights remain the school’s responsibility.</p>';if($manager){sv_form('lib_resource',['title'=>['Resource title','text'],'kind'=>['Type',['digital'=>'Digital resource','ebook'=>'Licensed ebook']],'url'=>['Publisher HTTPS address','url'],'licensor'=>['Licensor / rights statement','text'],'starts_on'=>['Licence starts','date'],'ends_on'=>['Licence ends','date'],'seats'=>['Licensed ebook seats','number','1']],'Register resource');sv_form('lib_disable_resource',['resource_id'=>['Resource ID','number']],'Disable resource access');}
 }elseif($view==='reservations'){
  $ids=$manager?'':implode(',',array_map('intval',array_keys($sc)));$rows=q("SELECT r.id,s.name,b.title,r.status,r.created_at FROM lib_reservations r JOIN students s ON s.id=r.student_id AND s.tenant_id=r.tenant_id JOIN books b ON b.id=r.book_id AND b.tenant_id=r.tenant_id WHERE r.tenant_id=?".($manager?'':' AND r.student_id IN ('.($ids?:'0').')').' ORDER BY r.id DESC LIMIT 200',[$tid])->fetchAll();op_table($rows,['ID','Student','Book','Status','Queued']);if($sc){sv_form('lib_reserve',$ef,'Reserve in waiting queue');sv_form('lib_cancel_reservation',$ef,'Cancel reservation');}
 }elseif($view==='labels'){
  echo '<p>Print these QR labels. A USB barcode scanner can also read a book’s existing ISBN into catalogue search. QR keys identify a title and never authorize a loan.</p><button class="btn" onclick="window.print()">Print labels</button><div style="display:flex;flex-wrap:wrap;gap:20px">';foreach($books as $b)echo '<div style="width:150px;text-align:center">'.lib_qr('LIB-'.$tid.'-'.$b['id']).'<strong>'.e($b['title']).'</strong><p>'.e('LIB-'.$tid.'-'.$b['id']).'</p></div>';echo '</div>';
 }else{
  $ids=implode(',',array_map('intval',array_keys($sc)));$where=$manager?'':' AND l.student_id IN ('.($ids?:'0').')';$loans=q("SELECT l.id,s.name,b.title,l.status,l.due_on,l.returned_at FROM lp_library_loans l JOIN students s ON s.id=l.student_id AND s.tenant_id=l.tenant_id JOIN books b ON b.id=l.book_id AND b.tenant_id=l.tenant_id WHERE l.tenant_id=?".$where.($view==='overdue'?" AND l.status='issued' AND l.due_on<CURRENT_DATE()":'').' ORDER BY l.id DESC LIMIT 300',[$tid])->fetchAll();op_table($loans,['Loan','Reader','Book','Status','Due','Returned']);
  if($manager&&$view==='loans'){foreach(['issue'=>'Issue requested copy','return'=>'Record return','reject'=>'Reject request','lost'=>'Record lost copy and charge','recover'=>'Recover lost copy'] as $a=>$label){$f=['loan_id'=>['Loan ID','number']];if($a==='issue')$f['due_on']=['Due date','date'];sv_form('lib_'.$a,$f,$label);}}
  if($manager&&$view==='overdue'){sv_form('lib_overdue',[],'Post daily in-app overdue reminders');sv_form('lib_fine',['loan_id'=>['Loan ID','number']],'Assess configured overdue fine once');echo '<p>Fines are frozen at first assessment, using the current configured daily rate and completed overdue days. Review and assess at return when a final amount is required. Loss charges use the replacement cost at recording. Existing Finance handles payment, receipts and any reviewed refund.</p>';}
  if($view==='history'){$users=[(int)$u['id']];foreach(array_keys($sc) as $sid)foreach(q("SELECT user_id FROM ecosystem_links WHERE tenant_id=? AND student_id=? AND relation_type='student'",[$tid,$sid])->fetchAll() as $link)$users[]=(int)$link['user_id'];$users=array_unique($users);op_table(q('SELECT u.name,r.title,a.expires_at,a.returned_at FROM lib_access a JOIN users u ON u.id=a.user_id AND u.tenant_id=a.tenant_id JOIN lib_resources r ON r.id=a.resource_id AND r.tenant_id=a.tenant_id WHERE a.tenant_id=?'.($manager?'':' AND a.user_id IN ('.implode(',',array_map('intval',$users)).')').' ORDER BY a.id DESC LIMIT 200',[$tid])->fetchAll(),['Ebook reader','Licensed title','Seat expires','Returned']);}
  if($view==='reports'){if(!$manager)throw new RuntimeException('Librarian access required for inventory reports.');op_table(q('SELECT COUNT(*) titles,COALESCE(SUM(copies),0) physical_copies,COALESCE(SUM(available),0) available,COALESCE(SUM(copies-available),0) issued FROM books WHERE tenant_id=?',[$tid])->fetchAll(),['Titles','Physical copies','Available','Issued']);op_table(q("SELECT status,COUNT(*) total FROM lp_library_loans WHERE tenant_id=? GROUP BY status",[$tid])->fetchAll(),['Loan status','Count']);}
 }
 echo '</section>';
